const items = $input.all();

// Lấy 100% ca bị vi phạm SLA/leo thang và ngẫu nhiên 20% ca thường
const sampled = items.filter(item => {
  const isPriority = item.json.sla_breached === 1 || item.json.last_alert_level !== 'NORMAL';
  return isPriority || Math.random() < 0.2;
});

// Đảm bảo có ít nhất 1 item để chạy tiếp
return sampled.length > 0 ? sampled : items.slice(0, 1);

