// Lấy output từ AI Agent (chỉ lấy bản ghi đầu tiên để tránh bị trùng item)
const rawItem = $input.first();
const text = rawItem.json.output || rawItem.json.text || '';

// Regex trích xuất điểm số từ văn bản đánh giá của AI
const getScore = (fieldName, defaultVal = 8) => {
  const regex = new RegExp(`${fieldName}[^0-9]*([0-9]+(?:\\.[0-9]+)?)\\s*\\/\\s*10`, 'i');
  const match = text.match(regex);
  return match ? parseFloat(match[1]) : defaultVal;
};

const greeting = getScore('greeting_score', 8);
const understanding = getScore('understanding_score', 8);
const policy = getScore('policy_accuracy_score', 8);
const tone = getScore('tone_score', 8);
const resolution = getScore('resolution_score', 8);

const total = (greeting + understanding + policy + tone + resolution) / 5;

// Kiểm tra vi phạm nghiêm trọng
const hasViolation = /has_critical_violation\s*[:=]\s*true/i.test(text) || text.includes('vi phạm nghiêm trọng');

let grade = 'PASSED';
if (total < 5 || hasViolation) {
  grade = 'FAILED';
} else if (total < 7.5) {
  grade = 'NEEDS_IMPROVEMENT';
}

return [
  {
    json: {
      ticket_id: $('Loop Over Items').item.json.id,
      total_score: Number(total.toFixed(2)),
      grade: grade,
      has_violation: hasViolation ? 1 : 0,
      details: text.length > 500 ? text.substring(0, 500) + '...' : text
    }
  }
];
